// SkadiAsset.swift — baked Skadi (the Corrupting Heart) animation clips.
//
// Rendered OFFLINE from arkdock's Spine data via headless pixi-spine, sampled at a
// fixed 10fps (so frame count tracks each clip's real duration — no speed distortion),
// quantized, and base64-embedded (bare-binary friendly). Play back at 10fps.
//   base (default_build, 200px):   Relax / Move / Interact / Sleep
//   battle (default_front, 240px): Skill_2_Loop / Skill_3_Loop
// See tools/bake-operator/.

import CoreGraphics
import Foundation
import ImageIO

enum SkadiAsset {
    static let fps: Double = 10
    nonisolated(unsafe) static let relax    = slice(decode(relaxB64), 200)
    nonisolated(unsafe) static let move     = slice(decode(moveB64), 200)
    nonisolated(unsafe) static let interact = slice(decode(interactB64), 200)
    nonisolated(unsafe) static let sleep    = slice(decode(sleepB64), 200)
    nonisolated(unsafe) static let skill2   = slice(decode(skill2B64), 240)
    nonisolated(unsafe) static let skill3   = slice(decode(skill3B64), 240)

    private static func decode(_ b64: String) -> CGImage? {
        guard let data = Data(base64Encoded: b64),
              let src = CGImageSourceCreateWithData(data as CFData, nil),
              let img = CGImageSourceCreateImageAtIndex(src, 0, nil) else { return nil }
        return img
    }
    private static func slice(_ sheet: CGImage?, _ frameW: Int) -> [CGImage] {
        guard let sheet = sheet, sheet.width >= frameW else { return [] }
        var out: [CGImage] = []
        for i in 0..<(sheet.width / frameW) {
            if let f = sheet.cropping(to: CGRect(x: i * frameW, y: 0, width: frameW, height: sheet.height)) {
                out.append(f)
            }
        }
        return out
    }

